<!-- --------- новый код chat: явный выбор списаний при недостатке остатка -->
<template><WorkOrderDialog title="Выберите списания для удаления" @close="$emit('close')"><p>Изменение поступления создаёт нехватку <strong>{{ quantityDisplay(shortage) }} {{ unit }}</strong>. Выберите строки использования, которые нужно убрать из работ. Сами работы сохранятся.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th></th><th>Дата / смена</th><th>Работа / позиция</th><th>Количество</th></tr></thead><tbody><tr v-for="u in usages" :key="u.ID"><td><input v-model="selected" type="checkbox" :value="u.ID" :aria-label="`Убрать списание ${u.ID}`"></td><td>{{ u.date }} / {{ u.number }}</td><td>{{ u.task_name }}<div class="text-secondary">{{ u.block_name }} · {{ u.position_number }}</div></td><td>{{ quantityDisplay(u.quantity_thousandths) }} {{ unit }}</td></tr></tbody></table></div><div class="d-flex justify-content-between align-items-center"><span>Выбрано: {{ quantityDisplay(total) }} {{ unit }}</span><button class="btn btn-primary btn-sm" :disabled="total<shortage" @click="$emit('selected',selected)">Подтвердить и сохранить</button></div></WorkOrderDialog></template>
<script setup>
import {ref,computed} from 'vue';import WorkOrderDialog from './WorkOrderDialog.vue';import {quantityDisplay} from './workOrderHelpers';const props=defineProps({usages:Array,shortage:Number,unit:String});defineEmits(['close','selected']);const selected=ref([]);const total=computed(()=>props.usages.filter(u=>selected.value.includes(u.ID)).reduce((s,u)=>s+u.quantity_thousandths,0));
</script>
<!-- --------- конец нового кода chat -->
